update public.products
set name = case id::text
  when '00000000-0000-4000-8000-000000000004' then 'VIP Test 4'
  when '00000000-0000-4000-8000-000000000005' then 'VIP Test 5'
  when '00000000-0000-4000-8000-000000000006' then 'VIP Test 6'
  when '00000000-0000-4000-8000-000000000007' then 'VIP Test 7'
  when '00000000-0000-4000-8000-000000000008' then 'VIP Test 8'
  when '00000000-0000-4000-8000-000000000009' then 'VIP Test 9'
end
where id::text in (
  '00000000-0000-4000-8000-000000000004',
  '00000000-0000-4000-8000-000000000005',
  '00000000-0000-4000-8000-000000000006',
  '00000000-0000-4000-8000-000000000007',
  '00000000-0000-4000-8000-000000000008',
  '00000000-0000-4000-8000-000000000009'
);
